/*Para hacer el tigger de perfil por cada usuario nuevo */
-- Cambiar a la base de datos correcta
USE [ptstools_HelpDesk]
GO
-- Crear el trigger
CREATE TRIGGER trg_CreateProfileOnUserInsert
ON [dbo].[User]  -- Asegúrate de que la tabla es correcta
AFTER INSERT
AS
BEGIN
    
    -- Insertar un perfil por defecto para cada nuevo usuario
    INSERT INTO [dbo].[usr_profile] 
    (id_User, nombre, email, password, Género, Estado, Foto_usuario, Cel, [fecha nacimeinto], createdAt, updateAt)
    SELECT 
        i.id AS id_User,          -- Asigna el id del nuevo usuario como id_User
        i.nombre,                 -- Usa el nombre del usuario para el perfil
        i.email,			-- Usa el email del usuario para el perfil
		i.password,
        NULL AS Género,  -- Valor por defecto para género
        NULL AS Estado,    -- Valor por defecto para estado
        NULL AS Foto_usuario,  -- Usa la imagen predeterminada
        NULL AS Cel,              -- Número de celular vacío por defecto
		NULL AS [fecha nacimeinto],
        GETDATE() AS createdAt,    -- Fecha actual para createdAt
		GETDATE() AS updateAt
    FROM inserted i;
	UPDATE usr_profile
	SET Foto_usuario = 
	WHERE id_User IN (SELECT id FROM inserted);
END;
